window.MI = window.MI || {};
(function (MI) {
  'use strict';
  /* 全站插图只保留这三张。
     原先 12 张里，9 张是各页头部与首屏的装饰配图 —— 它们占掉构建产物
     一半体积（688 KB / 1.32 MB），却对「把念头变成七天计划」这件事
     零贡献：用户每次进来都要先划过一张图才能开始做事。
     留下的是三种**功能性**插图，它们在页面本身没有内容可看时负责填空：
       archive —— 档案柜空状态
       missing —— 路由 404
       help    —— 使用说明弹层
     加图之前先问一句：这张图是在替代内容，还是只是陪衬？
     只有前者值得付体积。 */
  MI.art = {
    archive: 'data:image/jpeg;base64,',
    help: 'data:image/jpeg;base64,',
    missing: 'data:image/jpeg;base64,',
  };
  MI.figure = function (name, alt, extra) {
    var src = MI.art[name];
    if (!src) return '';
    var cls = 'illu illu-' + name + (extra ? ' ' + extra : '');
    return '<figure class="' + cls + '">' +
      '<img src="' + src + '" alt="' + (alt || '') + '"></figure>';
  };
})(window.MI);
